126	// Org returns an organization.
127	func (s *Store) Org(id string) (Org, bool) {
128		s.mu.Lock()
129		defer s.mu.Unlock()
130		o, ok := s.orgs[id]
131		return o, ok
132	}
133	
134	// UpdateOrg changes an organization with f, which may refuse with an error.
135	func (s *Store) UpdateOrg(id string, f func(*Org) error) (Org, error) {
136		s.mu.Lock()
137		defer s.mu.Unlock()
138		o, ok := s.orgs[id]
139		if !ok {
140			return Org{}, ErrNotFound
141		}
142		if err := f(&o); err != nil {
143			return Org{}, err
144		}
145		o.ID = id
146		if err := checkOrg(o); err != nil {
147			return Org{}, err
148		}
149		s.orgs[id] = o
150		return o, nil
151	}
