func TestSoftDeleteCustomers(t *testing.T) {
	e := apitest.New(t)
	jane := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	plan := e.CreatePlan(e.Acme, "Pro", "USD", "20.00")
	var sub store.Subscription
	e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": jane.ID, "plan_id": plan.ID}, &sub)
	if r := e.Do("DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil); r.Code != http.StatusConflict || r.Map(t)["error"] != "has_active_subscriptions" {
		t.Fatalf("delete with an active subscription: %s", r)
	}
	e.MustDo(http.StatusOK, "POST", "/v1/subscriptions/"+sub.ID+"/cancel", e.Acme.Key, nil, nil)

	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil, nil)
	var evs struct{ Items []store.Event }
	e.MustDo(http.StatusOK, "GET", "/v1/events?type=customer.deleted", e.Acme.Key, nil, &evs)
	if len(evs.Items) != 1 {
		t.Fatalf("customer.deleted events = %+v", evs)
	}
	if r := e.Do("GET", "/v1/customers/"+jane.ID, e.Acme.Key, nil); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("GET deleted customer: %s", r)
	}
	if r := e.Do("PATCH", "/v1/customers/"+jane.ID, e.Acme.Key, map[string]string{"name": "X"}); r.Code != http.StatusNotFound {
		t.Fatalf("PATCH deleted customer: %s", r)
	}
	if r := e.Do("DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("DELETE deleted customer: %s", r)
	}
	for _, path := range []string{"/v1/customers", "/v1/customers?q=jane", "/v1/customers?email=jane@example.com"} {
		var page struct{ Items []store.Customer }
		e.MustDo(http.StatusOK, "GET", path, e.Acme.Key, nil, &page)
		if len(page.Items) != 0 {
			t.Fatalf("GET %s lists the deleted customer: %+v", path, page.Items)
		}
	}
	r := e.MustDo(http.StatusOK, "GET", "/v1/customers/export.csv", e.Acme.Key, nil, nil)
	if rows, err := csv.NewReader(strings.NewReader(string(r.Body))).ReadAll(); err != nil || len(rows) != 1 {
		t.Fatalf("export lists the deleted customer: %v, %v", rows, err)
	}
	if r := e.Do("POST", "/v1/invoices", e.Acme.Key, map[string]any{"customer_id": jane.ID, "currency": "USD",
		"lines": []map[string]any{{"description": "Consulting", "quantity": 1, "unit_amount": 100}}}); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("invoice for deleted customer: %s", r)
	}
	if r := e.Do("POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": jane.ID, "plan_id": plan.ID}); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("subscription for deleted customer: %s", r)
	}

	// The invoice keeps its customer, marked deleted.
	type invoices struct {
		Items []struct {
			Customer *struct {
				ID, Name, Email string
				Deleted         bool
			} `json:"customer"`
		} `json:"items"`
	}
	var invs invoices
	e.MustDo(http.StatusOK, "GET", "/v1/invoices?customer_id="+jane.ID, e.Acme.Key, nil, &invs)
	if len(invs.Items) != 1 || invs.Items[0].Customer == nil || invs.Items[0].Customer.ID != jane.ID ||
		invs.Items[0].Customer.Email != "jane@example.com" || !invs.Items[0].Customer.Deleted {
		t.Fatalf("invoices of a deleted customer = %+v", invs)
	}

	// The address is free again, but a restore then conflicts with the new customer.
	jane2 := e.CreateCustomer(e.Acme, "Jane Again", "JANE@example.com")
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusConflict || r.Map(t)["error"] != "email_taken" {
		t.Fatalf("restore with the address in use: %s", r)
	}
	if r := e.Do("POST", "/v1/customers/"+jane2.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("restore of a customer that is not deleted: %s", r)
	}
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+jane2.ID, e.Acme.Key, nil, nil)
	var restored store.Customer
	e.MustDo(http.StatusOK, "POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil, &restored)
	if restored.ID != jane.ID || restored.DeletedAt != nil {
		t.Fatalf("restored = %+v", restored)
	}
	e.MustDo(http.StatusOK, "GET", "/v1/customers/"+jane.ID, e.Acme.Key, nil, &restored)
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("restore of a customer that is not deleted: %s", r)
	}
	invs = invoices{}
	e.MustDo(http.StatusOK, "GET", "/v1/invoices?customer_id="+jane.ID, e.Acme.Key, nil, &invs)
	if len(invs.Items) != 1 || invs.Items[0].Customer == nil || invs.Items[0].Customer.Deleted {
		t.Fatalf("invoices of a restored customer = %+v", invs)
	}

	// After 30 days a deleted customer cannot be restored, and purging removes it; its invoice then has no customer.
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil, nil)
	e.Clock.Advance(30 * 24 * time.Hour)
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusOK {
		t.Fatalf("restore at 30 days: %s", r)
	}
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil, nil)
	e.Clock.Advance(time.Second)
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("restore after 30 days: %s", r)
	}
	if n := e.Store.PurgeDeletedCustomers(e.Clock.Now()); n != 2 { // jane and jane2
		t.Fatalf("purged %d customers, want 2", n)
	}
	invs = invoices{}
	e.MustDo(http.StatusOK, "GET", "/v1/invoices?customer_id="+jane.ID, e.Acme.Key, nil, &invs)
	if len(invs.Items) != 1 || invs.Items[0].Customer != nil {
		t.Fatalf("invoice of a purged customer = %+v", invs)
	}
}

